:root {
            --portal-bg: #f7fafc;
            --portal-bg-soft: #eef4f8;
            --portal-border: #dbe5ef;
            --portal-mobile-nav-height: 4.65rem;
            --portal-topline-min-height: 3rem;
            --bsk-blue: #123f73;
            --bsk-blue-light: #1f5d9e;
            --bsk-blue-dark: #0b2b4c;
            --bsk-yellow: #f5c542;
            --bsk-yellow-dark: #d6a820;
            --bsk-green: #4ade80;
            --bsk-green-light: #86efac;
            --bsk-green-rgb: 74, 222, 128;
        }
        html {
            background: var(--portal-bg);
            height: 100%;
            height: 100dvh;
            overflow: hidden;
            scrollbar-gutter: stable;
        }
        body {
            font-family: 'Inter', sans-serif;
            -webkit-tap-highlight-color: transparent;
            background: linear-gradient(180deg, #fbfdff 0%, var(--portal-bg) 48%, var(--portal-bg-soft) 100%);
            /* Keep document from growing so only .portal-main-shell scrolls;
               otherwise opening collapsible cards toggles the window scrollbar and shifts layout sideways. */
            height: 100%;
            height: 100dvh;
            max-height: 100dvh;
            min-height: 0; /* override Tailwind min-h-screen so mobile chrome can't push content under the nav */
            overflow: hidden;
        }
        .portal-sidebar-shell {
            background:
                radial-gradient(circle at 20% 0%, rgba(245, 197, 66, 0.12), transparent 34%),
                linear-gradient(180deg, #ffffff 0%, #f7fafc 46%, #eef4f8 100%);
            border-right: 1px solid rgba(18, 63, 115, 0.12);
            box-shadow: 12px 0 34px rgba(15, 23, 42, 0.04);
        }
        .portal-mobile-chrome {
            background: linear-gradient(90deg, #0b2b4c 0%, #123f73 54%, #1f5d9e 100%);
        }
        .portal-mobile-header {
            background:
                radial-gradient(circle at 8% 0%, rgba(245, 197, 66, 0.16), transparent 36%),
                linear-gradient(135deg, rgba(255, 255, 255, 0.96) 0%, rgba(247, 250, 252, 0.94) 62%, rgba(238, 244, 248, 0.96) 100%);
            backdrop-filter: blur(16px);
            border-bottom: 1px solid rgba(18, 63, 115, 0.12);
            box-sizing: border-box;
            box-shadow: 0 8px 24px rgba(15, 23, 42, 0.06);
            height: calc(3.5rem + env(safe-area-inset-top, 0px));
            left: 0;
            padding-top: calc(0.75rem + env(safe-area-inset-top, 0px));
            position: fixed;
            right: 0;
            top: 0;
            z-index: 50;
        }
        .portal-main-shell {
            min-height: 0;
            overflow-x: hidden;
            padding-top: calc(3.5rem + env(safe-area-inset-top, 0px));
            scrollbar-gutter: stable;
        }
        @media (max-width: 767px) {
            /* No reserved scrollbar strip on phone — touch scroll only */
            html,
            .portal-main-shell {
                scrollbar-gutter: auto;
            }
            .portal-main-shell {
                margin-bottom: calc(var(--portal-mobile-nav-height) + env(safe-area-inset-bottom, 0px));
                scrollbar-width: none;
            }
            .portal-main-shell::-webkit-scrollbar {
                display: none;
                width: 0;
                height: 0;
            }
            /* Keep the scrollport above the fixed mobile nav so content cannot sit under it. */
            #main-view.portal-main-view {
                padding-bottom: 1.25rem;
            }
        }
        @media (min-width: 768px) {
            .portal-main-shell {
                padding-top: 0;
            }
        }
        .portal-view {
            margin-top: 0;
            width: 100%;
        }
        .portal-page {
            margin-left: auto;
            margin-right: auto;
            max-width: 88rem;
            width: 100%;
        }
        .portal-page-wide {
            max-width: 96rem;
        }
        .portal-page-narrow {
            max-width: 64rem;
        }
        @media (max-width: 767px) {
            .portal-view-mobile-dragging {
                will-change: transform, opacity;
                touch-action: pan-y;
            }
            .portal-view-swipe-enter-left {
                animation: portal-view-swipe-in-left 680ms cubic-bezier(0.16, 1, 0.3, 1);
                will-change: transform, opacity;
            }
            .portal-view-swipe-enter-right {
                animation: portal-view-swipe-in-right 680ms cubic-bezier(0.16, 1, 0.3, 1);
                will-change: transform, opacity;
            }
        }
        @media (prefers-reduced-motion: reduce) {
            .portal-view-swipe-enter-left,
            .portal-view-swipe-enter-right {
                animation: none;
            }
        }
        @keyframes portal-view-swipe-in-left {
            from {
                opacity: 0.58;
                transform: translate3d(var(--portal-swipe-enter-distance, 88px), 0, 0);
            }
            to {
                opacity: 1;
                transform: translate3d(0, 0, 0);
            }
        }
        @keyframes portal-view-swipe-in-right {
            from {
                opacity: 0.58;
                transform: translate3d(calc(var(--portal-swipe-enter-distance, 88px) * -1), 0, 0);
            }
            to {
                opacity: 1;
                transform: translate3d(0, 0, 0);
            }
        }
        .portal-view > :first-child {
            margin-top: 0;
        }
        .portal-main-view,
        #main-view {
            min-width: 0;
            padding-bottom: 1.5rem;
            padding-top: 1rem;
        }
        @media (max-width: 767px) {
            #main-view.portal-swipe-peeking {
                overflow: hidden;
                position: relative;
            }
            .portal-view-mobile-dragging {
                position: relative;
                z-index: 1;
            }
            .portal-view-mobile-peek {
                display: block;
                left: 1rem;
                pointer-events: none;
                position: absolute;
                right: 1rem;
                top: 1rem;
                will-change: transform, opacity;
                width: auto;
                z-index: 2;
            }
        }
        @media (min-width: 768px) {
            .portal-main-view,
            #main-view {
                padding-bottom: 2rem;
            }
        }
        #stats-tab-hero:not(.stats-hero-panel):not(.stats-chrome):empty {
            display: none;
        }
        .stats-hero-lag-filter,
        .stats-chrome > .stats-hero-lag-filter {
            margin: 0 auto 0.65rem;
            max-width: 100%;
            width: fit-content;
        }
        .stats-hero-panel > .stats-hero-lag-filter {
            margin-bottom: 0.85rem;
        }
        .portal-mobile-admin-btn {
            background: rgba(255, 255, 255, 0.72);
            border: 1px solid rgba(18, 63, 115, 0.12);
            border-radius: 0.75rem;
            box-shadow: 0 8px 18px rgba(15, 23, 42, 0.05);
            color: #123f73;
        }
        .portal-mobile-admin-btn.is-active {
            background: rgba(245, 197, 66, 0.2);
            border-color: rgba(245, 197, 66, 0.5);
            color: #0b2b4c;
        }
        .portal-mobile-tools {
            position: relative;
        }
        .portal-mobile-tools-menu {
            background: rgba(255, 255, 255, 0.98);
            border: 1px solid rgba(18, 63, 115, 0.12);
            border-radius: 1rem;
            box-shadow: 0 18px 42px rgba(15, 23, 42, 0.14);
            min-width: 11rem;
            overflow: hidden;
            padding: 0.35rem;
            position: absolute;
            right: 0;
            top: calc(100% + 0.55rem);
            z-index: 60;
        }
        .portal-mobile-tools-item {
            align-items: center;
            border-radius: 0.75rem;
            color: #123f73;
            display: flex;
            font-size: 0.8rem;
            font-weight: 850;
            gap: 0.65rem;
            padding: 0.7rem 0.75rem;
            text-align: left;
            width: 100%;
        }
        .portal-mobile-tools-item i {
            color: #64748b;
            text-align: center;
            width: 1rem;
        }
        .portal-mobile-tools-item:hover {
            background: rgba(245, 197, 66, 0.14);
        }
        .portal-mobile-brand-lockup {
            align-items: center;
            display: inline-flex;
            min-height: 2.55rem;
            padding-left: 1.48rem;
            position: relative;
        }
        .portal-mobile-brand-chip {
            align-items: center;
            background:
                radial-gradient(circle at 88% 8%, rgba(245, 197, 66, 0.18), transparent 34%),
                linear-gradient(135deg, #0b2b4c 0%, #123f73 66%, #1f5d9e 100%);
            border: 1px solid rgba(245, 197, 66, 0.22);
            border-radius: 0.64rem;
            box-shadow: 0 7px 15px rgba(11, 43, 76, 0.11);
            display: inline-flex;
            overflow: visible;
            padding: 0.18rem 0.55rem 0.19rem 0.86rem;
        }
        .portal-brand-panel {
            background:
                radial-gradient(circle at 88% 8%, rgba(245, 197, 66, 0.24), transparent 28%),
                linear-gradient(135deg, #0b2b4c 0%, #123f73 64%, #1f5d9e 100%);
            border: 1px solid rgba(245, 197, 66, 0.22);
            border-radius: 1.25rem;
            box-shadow: 0 14px 30px rgba(11, 43, 76, 0.18);
            min-height: 5rem;
            padding: 1rem;
        }
        .portal-brand-mark {
            align-items: center;
            background: transparent;
            border: 0;
            border-radius: 0;
            box-shadow: none;
            color: #f5c542;
            display: flex;
            height: 3.1rem;
            justify-content: center;
            overflow: visible;
            position: relative;
            width: 2.9rem;
        }
        .portal-brand-mark::after {
            content: none;
            display: none;
        }
        .portal-brand-mark-desktop .portal-brand-shield {
            height: 3.35rem;
            width: 3.1rem;
        }
        .portal-brand-mark-sm {
            border-radius: 0.75rem;
            height: 2.25rem;
            width: 2.25rem;
        }
        .portal-mobile-brand-mark {
            background: transparent;
            border: 0;
            box-shadow: none;
            color: #f5c542;
            left: 0;
            overflow: visible;
            position: absolute;
            top: 50%;
            transform: translateY(-50%);
            z-index: 2;
        }
        .portal-mobile-brand-mark::before,
        .portal-mobile-brand-mark::after {
            content: none;
            display: none;
        }
        .portal-brand-shield {
            display: block;
            filter: drop-shadow(0 3px 7px rgba(11, 43, 76, 0.16));
            height: 2.55rem;
            width: 2.42rem;
        }
        .portal-brand-shield-border {
            fill: #d6dee9;
        }
        .portal-brand-shield-fill-yellow {
            fill: #f5c542;
        }
        .portal-brand-shield-fill-blue {
            fill: #123f73;
        }
        .portal-brand-shield-divider {
            fill: rgba(255, 255, 255, 0.42);
        }
        .portal-brand-shield-outline {
            fill: none;
            stroke: #d6dee9;
            stroke-linejoin: round;
            stroke-width: 2.2;
        }
        .portal-mobile-brand-chip .portal-brand-football {
            display: inline-block;
            margin-left: 0.16rem;
        }
        .portal-brand-title {
            font-size: 1.05rem;
            font-weight: 900;
            letter-spacing: -0.01em;
            line-height: 1;
            text-transform: uppercase;
        }
        .portal-brand-title-mobile {
            font-size: 0.96rem;
            letter-spacing: -0.015em;
        }
        .portal-brand-bsk {
            color: #f5c542;
        }
        .portal-brand-football {
            color: #ffffff;
        }
        .portal-brand-subtitle {
            color: rgba(255, 255, 255, 0.74);
            display: block;
            font-size: 0.7rem;
            font-weight: 700;
            letter-spacing: 0.02em;
            margin-top: 0.3rem;
        }
        .portal-nav-link {
            border-color: transparent;
            color: #526173 !important;
            font-size: 0.9rem;
            font-weight: 850;
        }
        .portal-nav-link i {
            color: #7c8ca0;
            transition: color 150ms ease, transform 150ms ease;
        }
        .portal-nav-link:hover {
            background: rgba(255, 255, 255, 0.78) !important;
            border-color: rgba(18, 63, 115, 0.12) !important;
            box-shadow: 0 8px 20px rgba(15, 23, 42, 0.05);
            color: #123f73 !important;
        }
        .portal-nav-link:hover i {
            color: #123f73;
            transform: translateX(1px);
        }
        .portal-sidebar-footer {
            border-top: 1px solid rgba(18, 63, 115, 0.12);
            color: #64748b;
        }
        .portal-sidebar-footer p:first-child {
            color: #123f73;
        }
        .portal-sidebar-admin-btn {
            background: rgba(255, 255, 255, 0.72);
            border: 1px solid rgba(18, 63, 115, 0.12);
            border-radius: 0.75rem;
            box-shadow: 0 8px 18px rgba(15, 23, 42, 0.05);
            color: #123f73;
        }
        .portal-sidebar-admin-btn:hover {
            background: rgba(245, 197, 66, 0.16);
            border-color: rgba(245, 197, 66, 0.4);
            color: #0b2b4c;
        }
        .portal-mobile-nav-shell {
            --portal-mobile-nav-progress: 0;
            --portal-mobile-nav-item-count: 5;
            background: rgba(255, 255, 255, 0.95);
            backdrop-filter: blur(16px);
            border-color: rgba(18, 63, 115, 0.12);
            bottom: 0;
            box-sizing: border-box;
            color: #64748b;
            height: calc(var(--portal-mobile-nav-height) + env(safe-area-inset-bottom, 0px));
            left: 0;
            padding: 0.45rem 0.4rem calc(0.25rem + env(safe-area-inset-bottom, 0px));
            position: fixed;
            right: 0;
            z-index: 40;
        }
        .portal-mobile-nav-shell .mobile-nav-btn {
            color: #64748b;
            height: 3.55rem;
            min-width: 0;
            position: relative;
            z-index: 1;
        }
        .portal-mobile-nav-shell .mobile-nav-btn:hover {
            color: #123f73;
        }
        .portal-mobile-nav-indicator {
            background:
                radial-gradient(circle at 50% 0%, rgba(245, 197, 66, 0.34), transparent 64%),
                rgba(18, 63, 115, 0.07);
            border: 1px solid rgba(245, 197, 66, 0.24);
            border-radius: 1.15rem;
            bottom: calc(0.42rem + env(safe-area-inset-bottom, 0px));
            box-shadow: 0 10px 22px rgba(15, 23, 42, 0.08);
            left: 0.4rem;
            pointer-events: none;
            position: absolute;
            top: 0.45rem;
            transform: translate3d(calc(var(--portal-mobile-nav-progress) * 100%), 0, 0);
            transition: transform 260ms cubic-bezier(0.22, 1, 0.36, 1);
            width: calc((100% - 0.8rem) / var(--portal-mobile-nav-item-count));
            z-index: 0;
        }
        .portal-mobile-nav-shell.portal-mobile-nav-swiping .portal-mobile-nav-indicator {
            transition: none;
        }
        .portal-mobile-nav-shell.portal-mobile-nav-swiping .mobile-nav-btn.active-nav,
        .portal-mobile-nav-shell.portal-mobile-nav-settling .mobile-nav-btn.active-nav {
            background: transparent;
            box-shadow: none;
            color: #64748b !important;
        }
        .portal-page-toolbar {
            display: flex;
            flex-wrap: wrap;
            gap: 0.5rem;
            margin-top: 1rem;
            max-width: 100%;
        }
        .portal-page-toolbar.is-detached {
            justify-content: center;
            margin-top: 0;
        }
        .portal-segmented {
            align-items: center;
            background: transparent;
            border: 0;
            border-radius: 0;
            box-shadow: none;
            display: inline-flex;
            gap: 0.9rem;
            height: auto;
            max-width: 100%;
            overflow-x: auto;
            padding: 0;
            scrollbar-width: none;
            -webkit-overflow-scrolling: touch;
        }
        .portal-segmented::-webkit-scrollbar {
            display: none;
        }
        .portal-segment-btn {
            background: transparent;
            border: 1px solid transparent;
            border-radius: 999px;
            color: #64748b;
            flex: 0 0 auto;
            font-size: 0.6875rem;
            font-weight: 800;
            height: auto;
            padding: 0.4rem 0.75rem;
            transition: background 150ms ease, border-color 150ms ease, color 150ms ease;
            white-space: nowrap;
        }
        .portal-segment-btn:hover {
            background: rgba(18, 63, 115, 0.06);
            color: #123f73;
        }
        .portal-segment-btn.is-active {
            background: rgba(245, 197, 66, 0.14) !important;
            border-color: rgba(245, 197, 66, 0.28) !important;
            box-shadow: none;
            color: #0b2b4c !important;
        }
        .portal-segment-btn.is-active:hover {
            background: rgba(245, 197, 66, 0.2) !important;
            border-color: rgba(245, 197, 66, 0.36) !important;
            color: #0b2b4c !important;
        }
        .portal-inline-select {
            align-items: center;
            background: #ffffff;
            border: 1px solid #e2e8f0;
            border-radius: 0.875rem;
            box-shadow: 0 1px 3px rgba(15, 23, 42, 0.06);
            display: inline-flex;
            flex: 0 0 auto;
            height: 2.5rem;
            padding: 0 0.75rem;
        }
        .portal-status-label {
            align-items: center;
            background: #f5c542;
            border: 1px solid rgba(214, 168, 32, 0.45);
            border-radius: 999px;
            box-shadow: 0 2px 6px rgba(214, 168, 32, 0.12);
            color: #0b2b4c;
            display: inline-flex;
            font-size: 0.56rem;
            font-weight: 900;
            gap: 0.35rem;
            letter-spacing: 0.1em;
            line-height: 1;
            padding: 0.3rem 0.58rem;
            text-transform: uppercase;
            white-space: nowrap;
        }
        .portal-status-label i {
            color: #0b2b4c;
            font-size: 0.5rem;
        }
        .portal-status-label-sm {
            font-size: 0.46rem;
            gap: 0.28rem;
            letter-spacing: 0.09em;
            padding: 0.22rem 0.46rem;
        }
        .dashboard-hero-card {
            background:
                radial-gradient(circle at 0% 0%, rgba(245, 197, 66, 0.28), transparent 30%),
                radial-gradient(circle at 100% 14%, rgba(31, 93, 158, 0.48), transparent 34%),
                linear-gradient(135deg, #123f73 0%, #0b2b4c 58%, #071f38 100%);
            border-color: rgba(245, 197, 66, 0.22);
            box-shadow: 0 20px 46px rgba(11, 43, 76, 0.2);
        }
        .dashboard-hero-card::before {
            background: linear-gradient(90deg, #f5c542 0%, rgba(245, 197, 66, 0.32) 46%, rgba(255, 255, 255, 0.08) 100%);
            content: "";
            height: 0.25rem;
            left: 0;
            position: absolute;
            right: 0;
            top: 0;
        }
        .dashboard-hero-content {
            display: flex;
            flex-direction: column;
            gap: 1.35rem;
        }
        .dashboard-hero-top {
            align-items: center;
            border-bottom: 1px solid rgba(255, 255, 255, 0.12);
            display: flex;
            justify-content: space-between;
            gap: 1rem;
            padding-bottom: 0.95rem;
        }
        .dashboard-hero-meta {
            align-items: center;
            color: rgba(255, 255, 255, 0.9);
            display: inline-flex;
            flex-wrap: wrap;
            font-size: 0.74rem;
            font-weight: 900;
            gap: 0.45rem 0.8rem;
            letter-spacing: 0.01em;
        }
        .dashboard-hero-meta span + span {
            color: #f5c542;
        }
        .dashboard-hero-info-link {
            align-items: center;
            color: rgba(255, 255, 255, 0.88);
            display: inline-flex;
            flex: 0 0 auto;
            font-size: 0.72rem;
            font-weight: 900;
            gap: 0.45rem;
            transition: color 0.2s ease, transform 0.2s ease;
        }
        .dashboard-hero-info-link:hover {
            color: #f5c542;
            transform: translateX(1px);
        }
        .dashboard-matchup-grid {
            align-items: center;
            display: grid;
            gap: 1rem;
            grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
        }
        .dashboard-match-center {
            align-items: center;
            display: flex;
            flex-direction: column;
            gap: 0.45rem;
            min-width: 7.5rem;
            text-align: center;
        }
        .dashboard-match-center span {
            align-items: center;
            background: rgba(245, 197, 66, 0.16);
            border: 1px solid rgba(245, 197, 66, 0.34);
            border-radius: 999px;
            color: #f5c542;
            display: inline-flex;
            font-size: 0.64rem;
            font-weight: 950;
            height: 2.15rem;
            justify-content: center;
            width: 2.15rem;
        }
        .dashboard-match-center p {
            color: rgba(255, 255, 255, 0.72);
            font-size: 0.68rem;
            font-weight: 800;
            max-width: 8.5rem;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }
        .dashboard-team-block {
            align-items: center;
            display: flex;
            gap: 0.8rem;
            min-width: 0;
        }
        .dashboard-team-block.is-home {
            justify-content: flex-end;
            text-align: right;
        }
        .dashboard-team-block.is-away {
            justify-content: flex-start;
            text-align: left;
        }
        .dashboard-team-block h2 {
            align-items: center;
            color: #ffffff;
            display: inline-flex;
            font-size: 1.45rem;
            font-weight: 950;
            gap: 0.45rem;
            letter-spacing: 0;
            line-height: 1.06;
            max-width: 18rem;
            text-transform: uppercase;
        }
        .dashboard-team-block h2 span,
        .dashboard-team-block h2 {
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }
        .dashboard-team-block h2 i {
            color: rgba(245, 197, 66, 0.72);
            flex: 0 0 auto;
            font-size: 0.72rem;
            opacity: 0.72;
            transition: opacity 0.2s ease, transform 0.2s ease;
        }
        .dashboard-team-block h2:hover i {
            opacity: 1;
            transform: translateX(1px);
        }
        .dashboard-team-kicker {
            color: rgba(255, 255, 255, 0.48);
            font-size: 0.56rem;
            font-weight: 900;
            letter-spacing: 0.12em;
            margin-bottom: 0.28rem;
            text-transform: uppercase;
        }
        .dashboard-team-badge {
            align-items: center;
            background: rgba(255, 255, 255, 0.08);
            border: 1px solid rgba(255, 255, 255, 0.18);
            border-radius: 999px;
            box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.04), 0 8px 18px rgba(2, 6, 23, 0.16);
            color: rgba(255, 255, 255, 0.62);
            display: flex;
            flex: 0 0 auto;
            height: 2.6rem;
            justify-content: center;
            width: 2.6rem;
        }
        .dashboard-team-badge.is-bsk {
            border-color: rgba(245, 197, 66, 0.74);
