        /*
         * bsk-btn-system
         * primary = hovedhandling
         * secondary = vanlig handling
         * ghost = lav vekt
         * danger = destruktivt
         * warning = varsler/autofyll/tips/oppmerksomhet
         * icon = ikonknapp
         * chip = kompakt action/filter
         */
        .bsk-btn {
            align-items: center;
            border: 1px solid transparent;
            border-radius: 0.875rem;
            cursor: pointer;
            display: inline-flex;
            font-family: inherit;
            font-size: 0.75rem;
            font-weight: 800;
            gap: 0.4rem;
            justify-content: center;
            line-height: 1.15;
            min-height: 38px;
            padding: 0 0.85rem;
            text-decoration: none;
            transition: background 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease, color 0.2s ease, transform 0.2s ease, opacity 0.2s ease;
            white-space: nowrap;
            -webkit-tap-highlight-color: transparent;
        }
        .bsk-btn:disabled {
            cursor: not-allowed;
            opacity: 0.55;
        }
        .bsk-btn:active:not(:disabled) {
            transform: translateY(1px);
        }
        .bsk-btn-primary {
            background: var(--bsk-blue);
            border-color: rgba(31, 93, 158, 0.42);
            box-shadow: 0 1px 2px rgba(11, 43, 76, 0.2), inset 0 1px 0 rgba(255, 255, 255, 0.08);
            color: #ffffff;
        }
        .bsk-btn-primary:hover:not(:disabled) {
            background: var(--bsk-blue-light);
            border-color: rgba(31, 93, 158, 0.58);
            box-shadow: 0 2px 6px rgba(11, 43, 76, 0.24), inset 0 1px 0 rgba(255, 255, 255, 0.1);
            color: #ffffff;
        }
        .bsk-btn-primary:focus-visible {
            background: var(--bsk-blue-light);
            border-color: rgba(245, 197, 66, 0.42);
            box-shadow: 0 0 0 3px rgba(245, 197, 66, 0.28), 0 2px 6px rgba(11, 43, 76, 0.22);
            outline: none;
        }
        .bsk-btn-primary i {
            color: var(--bsk-yellow);
        }
        .match-detail-card .bsk-btn-primary,
        .bsk-modal-card .bsk-btn-primary {
            background: var(--bsk-blue-light);
            border-color: rgba(245, 197, 66, 0.24);
            box-shadow: 0 2px 8px rgba(2, 6, 23, 0.32), inset 0 1px 0 rgba(255, 255, 255, 0.1);
        }
        .match-detail-card .bsk-btn-primary:hover:not(:disabled),
        .bsk-modal-card .bsk-btn-primary:hover:not(:disabled),
