                vertical-align: baseline;
            }

            .match-print-bench-table th {
                border-bottom: 1pt solid #000000;
                font-size: 9pt;
                font-weight: 700;
                text-transform: uppercase;
            }

            .match-print-bench-table th:nth-child(1),
            .match-print-bench-table td:nth-child(1) {
                width: 2.6rem;
            }

            .match-print-bench-table th:nth-child(2),
            .match-print-bench-table td:nth-child(2) {
                width: 2.2rem;
            }

            .match-print-bench-table th:nth-child(4),
            .match-print-bench-table td:nth-child(4) {
                white-space: nowrap;
                width: 8.5rem;
            }

            .match-print-pos,
            .match-print-slot,
            .match-print-jersey,
            .match-print-minute {
                font-variant-numeric: tabular-nums;
                font-weight: 700;
            }

            .match-print-bench-table .match-print-name {
                font-weight: 400;
            }

            .match-print-empty {
                font-style: italic;
                margin: 0;
