            .match-print-samspill-section .match-game-plan-samspill-totals {
                display: grid;
                gap: 0.35rem;
                grid-template-columns: repeat(4, minmax(0, 1fr));
                list-style: none;
                margin: 0;
                padding: 0;
            }

            .match-print-samspill-section .match-game-plan-samspill-total {
                background: none;
                border: 0.75pt solid #000000;
                border-radius: 0;
                color: #000000;
                display: grid;
                gap: 0.08rem;
                justify-items: center;
                padding: 0.32rem 0.2rem 0.38rem;
                text-align: center;
            }

            .match-print-samspill-section .match-game-plan-samspill-total-label,
            .match-print-samspill-section .match-game-plan-samspill-total-value,
            .match-print-samspill-section .match-game-plan-samspill-total-best,
            .match-print-samspill-section .match-game-plan-samspill-total-names {
                color: #000000;
            }

            .match-print-samspill-section .match-game-plan-samspill-total-label {
                font-size: 8pt;
                font-weight: 700;
                letter-spacing: 0.05em;
                text-transform: uppercase;
            }

            .match-print-samspill-section .match-game-plan-samspill-total-value {
                font-size: 13pt;
                font-weight: 700;
                line-height: 1.1;
            }

            .match-print-samspill-section .match-game-plan-samspill-total-best {
                font-size: 9pt;
                font-weight: 700;
            }

            .match-print-samspill-section .match-game-plan-samspill-total-names {
                font-size: 8pt;
                font-weight: 400;
                letter-spacing: 0;
                line-height: 1.2;
                padding: 0;
                white-space: normal;
            }

            .match-print-pitch-chips {
                margin-top: 0.75rem;
            }

            .match-print-pitch-chips-list {
                display: grid;
                gap: 0.3rem;
                grid-template-columns: repeat(4, minmax(0, 1fr));
                list-style: none;
                margin: 0;
                padding: 0;
            }

            .match-print-pitch-chip {
                border: 0.75pt solid #000000;
                display: grid;
                gap: 0.06rem;
                justify-items: center;
                padding: 0.28rem 0.18rem 0.32rem;
                text-align: center;
            }

            .match-print-pitch-chip-label {
                font-size: 7.5pt;
                font-weight: 700;
                letter-spacing: 0.04em;
                text-transform: uppercase;
            }

            .match-print-pitch-chip-value {
                font-size: 12pt;
                font-weight: 700;
                line-height: 1.1;
            }

            .match-print-pitch-chip-note {
                font-size: 7pt;
                font-weight: 400;
                line-height: 1.2;
                white-space: normal;
            }

            .match-print-utvikling-section {
                margin-top: 0.95rem;
            }

            .match-print-utvikling-table {
                border-collapse: collapse;
                width: 100%;
            }

            .match-print-utvikling-table th,
            .match-print-utvikling-table td {
                border-bottom: 0.5pt solid #000000;
                padding: 0.22rem 0.35rem 0.22rem 0;
                text-align: left;
                vertical-align: top;
            }

            .match-print-utvikling-table th {
                border-bottom: 1pt solid #000000;
                font-size: 9pt;
                font-weight: 700;
                text-transform: uppercase;
            }

            .match-print-utvikling-table th:nth-child(1),
            .match-print-utvikling-table td:nth-child(1) {
                width: 2.2rem;
            }

            .match-print-utvikling-table th:nth-child(2),
            .match-print-utvikling-table td:nth-child(2) {
                width: 7.5rem;
            }

            .match-print-utvikling-text {
                font-size: 9pt;
                font-weight: 400;
                line-height: 1.35;
                white-space: pre-wrap;
                word-break: break-word;
            }

            .match-print-setpiece-grid {
                break-inside: avoid;
                display: grid;
                gap: 0.85rem 1.1rem;
                grid-template-columns: 1fr 1fr;
                margin-bottom: 0.9rem;
                page-break-inside: avoid;
            }

            .match-print-pitch {
                margin: 0 0 0.45rem;
                max-width: 100%;
            }

            .match-print-pitch-field {
                aspect-ratio: 2 / 3;
                border: 1.25pt solid #000000;
                margin: 0 auto;
                max-width: 11rem;
                overflow: visible;
                position: relative;
                width: 100%;
            }

            .match-print-pitch-halfway {
                border: 0;
                border-top: 1.5pt solid #000000;
                display: block;
                height: 0;
                left: 0;
                margin: 0;
                padding: 0;
                position: absolute;
                right: 0;
                top: 50%;
                transform: translateY(-50%);
                width: 100%;
                z-index: 1;
            }

            .match-print-pitch-center-circle {
                aspect-ratio: 1 / 1;
                border: 1pt solid #000000;
                border-radius: 999px;
                box-sizing: border-box;
                display: block;
                left: 50%;
                position: absolute;
                top: 50%;
                transform: translate(-50%, -50%);
                width: 28%;
                z-index: 1;
            }

            .match-print-pitch-box {
                border: 0.75pt solid #000000;
                border-top: 0;
                box-sizing: border-box;
                display: block;
                height: 18%;
                left: 22%;
                position: absolute;
                top: 0;
                width: 56%;
            }

            .match-print-pitch-marker {
                align-items: center;
                background: #ffffff;
                border: 1pt solid #000000;
                border-radius: 999px;
                display: inline-flex;
                font-family: Helvetica, Arial, sans-serif;
                font-size: 7.5pt;
                font-weight: 700;
                height: 1.05rem;
                justify-content: center;
                line-height: 1;
                position: absolute;
                transform: translate(-50%, -50%);
                width: 1.05rem;
                z-index: 2;
            }

            .match-print-pitch-ball {
                background: #000000;
                border-radius: 999px;
                display: block;
                height: 0.4rem;
                position: absolute;
                transform: translate(-50%, -50%);
                width: 0.4rem;
                z-index: 2;
            }

            .stats-awards-print-section h2 {
                margin-bottom: 0.45rem;
            }

            .stats-awards-print-grid {
                display: grid;
                gap: 0.55rem 0.85rem;
                grid-template-columns: repeat(2, minmax(0, 1fr));
            }

            .stats-awards-print-item h3 {
                font-size: 10pt;
                font-weight: 700;
                margin: 0 0 0.2rem;
            }

            .stats-awards-print-explain {
                font-size: 8pt;
                line-height: 1.3;
                margin: 0 0 0.28rem;
            }

            .stats-awards-print-table {
                border-collapse: collapse;
                width: 100%;
            }

            .stats-awards-print-table td {
                border-bottom: 0.4pt solid #000000;
                padding: 0.12rem 0.2rem 0.12rem 0;
                vertical-align: baseline;
            }

            .stats-awards-print-table tr:last-child td {
                border-bottom: 0;
            }

            .stats-awards-print-rank {
                font-weight: 700;
                width: 1.15rem;
                white-space: nowrap;
            }

            .stats-awards-print-name {
                width: auto;
            }

            .stats-awards-print-value {
                font-variant-numeric: tabular-nums;
                text-align: right;
                white-space: nowrap;
            }

            .stats-awards-print-item .match-print-empty {
                margin: 0;
            }
        }
